th {
  background-color: var(--light-color);
  color: var(--dark-color);
}

tr:nth-child(even) {
  background-color: #f2f2f2;
}

/* Phrases section */
.phrase-item {
  margin-bottom: 1rem;
  padding-bottom: 1rem;
  border-bottom: 1px solid #eee;
}

.japanese {
  font-size: 1.2rem;
  font-weight: bold;
  color: var(--primary-color);
}

.pronunciation {
  color: var(--secondary-color);
  font-style: italic;
  margin-left: 1rem;
}

.meaning {
  margin-top: 0.5rem;
}

/* Travel tips */
.tips-list li {
  margin-bottom: 1rem;
  list-style-type: none;
  padding-left: 2rem;
  position: relative;
}

.tips-list li:before {
  content: '✓';
  position: absolute;
  left: 0;
  color: var(--primary-color);
  font-weight: bold;
}

/* Print styles */
@media print {
  nav, footer, .no-print {
    display: none;
  }

  body, .container, .section {
    margin: 0;
    padding: 0;
    width: 100%;
    max-width: 100%;
  }

  h2 {
    page-break-after: avoid;
  }

  h3, h4 {
    page-break-after: avoid;
  }

  img {
    max-width: 100% !important;
  }

  p, table, .phrase-item, .tips-list li {
    page-break-inside: avoid;
  }
}

/* Responsive design */
@media screen and (max-width: 768px) {
  nav ul {
    flex-direction: column;
    align-items: center;
  }

  nav li {
    margin: 0.5rem 0;
  }

  .card-container {
    grid-template-columns: 1fr;
  }

  .section {
    padding: 1rem;
  }

  h1 {
    font-size: 2rem;
  }

  h2 {
    font-size: 1.5rem;
  }
}
</parameter>
</invoke>
